SELECT srr.id, srr.source_id, srrd.source_detail_id, srr.code, srr.source_code, srr.customer_id, srr.customer_name, srr.inventory_org_id, srr.inventory_org_name, srr.approve_status, srr.invalid_status, srrd.sku_id, srrd.sku_no, srrd.return_type_dict, srrd.return_qty, srrd.receive_qty, srr.seller_name, srr.return_date, srr.bill_date, srr.approve_user_name, srr.create_user_name, srr.create_time FROM so_return_receive_detail srrd INNER JOIN so_return_receive srr ON srrd.main_id = srr.id AND srrd.is_deleted = FALSE WHERE srr.is_deleted = FALSE
and srr.id in
#{item}
and srrd.sku_no in
#{item}
and srr.code = #{params.code}
and srr.source_code = #{params.sourceCode}
and srr.customer_id in
#{item}
and srr.inventory_org_id in
#{item}
and srr.seller_id in
#{item}
and srr.approve_status in
#{item}
and srr.invalid_status = #{params.invalidStatus}
and srrd.return_type_dict = #{params.returnTypeDict}
and srr.return_date >= #{params.returnDateList[0]} and (#{params.returnDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > srr.return_date
and srr.bill_date >= #{params.billDateList[0]} and (#{params.billDateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > srr.bill_date
and srr.create_user_id in
#{item}
and srr.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > srr.create_time
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
srr.create_time desc

